INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Kundenbeziehungen > Regelkonformität
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Regelkonformität in Kundenbeziehungen nur auf nationale Gesetze beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch EU-Recht wie DSGVO und interne Vorschriften gelten"}, {"text": "Ja", "correct": false, "because": "Regelkonformität ist umfassender"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Regelkonformität bei Kundenbeziehungen auch die Einhaltung von Datenschutzvorschriften umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "DSGVO ist zwingend für Kundendaten"}, {"text": "Nein", "correct": false, "because": "Datenschutz ist integraler Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Unternehmen bei der Regelkonformität von Kundenbeziehungen auf interne Richtlinien verzichten, wenn gesetzliche Vorgaben erfüllt sind?', 2, '[{"text": "Nein", "correct": true, "because": "Interne Richtlinien ergänzen gesetzliche Standards"}, {"text": "Ja", "correct": false, "because": "Interne Vorgaben sind oft strikter"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Regelkonformität in Kundenbeziehungen gewährleistet, wenn lediglich die vertraglichen Pflichten eingehalten werden?', 2, '[{"text": "Nein", "correct": true, "because": "Gesetzliche und ethische Regeln gehen darüber hinaus"}, {"text": "Ja", "correct": false, "because": "Verträge decken nicht alles ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Verstöße gegen die Regelkonformität in Kundenbeziehungen rechtliche Sanktionen nach sich ziehen?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzesverstöße können Bußgelder auslösen"}, {"text": "Nein", "correct": false, "because": "Sanktionen sind möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Regelung hat in der Regelkonformität von Kundenbeziehungen die höchste Priorität?', 2, '[{"text": "Gesetzliche Vorschriften", "correct": true, "because": "Sie sind zwingend und übergeordnet"}, {"text": "Interne Unternehmensrichtlinien", "correct": false, "because": "Unterliegen Gesetzen"}, {"text": "Kundenwünsche", "correct": false, "because": "Nicht rechtlich bindend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz ist für die Regelkonformität in Kundenbeziehungen bei der Datenverarbeitung maßgeblich?', 3, '[{"text": "DSGVO", "correct": true, "because": "Regelt EU-weit den Datenschutz"}, {"text": "BGB", "correct": false, "because": "Allgemeines Vertragsrecht"}, {"text": "UWG", "correct": false, "because": "Fokussiert Wettbewerb"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme stellt die Regelkonformität in Kundenbeziehungen sicher?', 2, '[{"text": "Regelmäßige Schulungen", "correct": true, "because": "Sensibilisiert Mitarbeiter"}, {"text": "Maximierung von Gewinnen", "correct": false, "because": "Kein Konformitätsfaktor"}, {"text": "Reduktion von Dokumentation", "correct": false, "because": "Gefährdet Nachweis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht bei fehlender Regelkonformität in Kundenbeziehungen?', 2, '[{"text": "Reputationsverlust", "correct": true, "because": "Vertrauen schwindet bei Verstößen"}, {"text": "Höhere Produktivität", "correct": false, "because": "Kein logischer Effekt"}, {"text": "Geringere Kosten", "correct": false, "because": "Verstöße erhöhen Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool unterstützt die Regelkonformität bei der Verwaltung von Kundenbeziehungen?', 2, '[{"text": "CRM-System", "correct": true, "because": "Dokumentiert regelkonform"}, {"text": "Textverarbeitung", "correct": false, "because": "Zu unspezifisch"}, {"text": "Buchhaltungssoftware", "correct": false, "because": "Finanzfokus"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche umfasst die Regelkonformität in Kundenbeziehungen?', 4, '[{"text": "Datenschutz", "correct": true, "because": "DSGVO ist maßgeblich"}, {"text": "Wettbewerbsrecht", "correct": true, "because": "UWG schützt Fairness"}, {"text": "Vertragsrecht", "correct": true, "because": "BGB regelt Vereinbarungen"}, {"text": "Produktentwicklung", "correct": false, "because": "Technisch, nicht regelbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gesetze sind für die Regelkonformität in Kundenbeziehungen relevant?', 3, '[{"text": "DSGVO", "correct": true, "because": "Schützt Kundendaten"}, {"text": "UWG", "correct": true, "because": "Regelt Wettbewerb"}, {"text": "BGB", "correct": true, "because": "Grundlage für Verträge"}, {"text": "EStG", "correct": false, "because": "Steuerrecht, kein Kundenfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern die Regelkonformität in Kundenbeziehungen?', 4, '[{"text": "Dokumentation von Prozessen", "correct": true, "because": "Nachweis der Einhaltung"}, {"text": "Schulung der Mitarbeiter", "correct": true, "because": "Vermeidet Verstöße"}, {"text": "Regelmäßige Audits", "correct": true, "because": "Überprüft Konformität"}, {"text": "Preissenkungen", "correct": false, "because": "Kein Regelbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen bei mangelnder Regelkonformität in Kundenbeziehungen?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Gesetzesverstöße ahndbar"}, {"text": "Kundenverlust", "correct": true, "because": "Vertrauen schwindet"}, {"text": "Rechtliche Streitigkeiten", "correct": true, "because": "Verstöße klagbar"}, {"text": "Technische Probleme", "correct": false, "because": "Kein direkter Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer regelkonformen Kundenbeziehung?', 3, '[{"text": "Transparente Kommunikation", "correct": true, "because": "Erfüllt UWG und DSGVO"}, {"text": "Einhaltung von Vereinbarungen", "correct": true, "because": "BGB-konform"}, {"text": "Datensicherheit", "correct": true, "because": "DSGVO-Pflicht"}, {"text": "Produktwerbung", "correct": false, "because": "Marketing, nicht Regel"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Regelkonformität schließt die Einhaltung der DSGVO ein. b) Sie ist nur für Großunternehmen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DSGVO ja, gilt für alle Unternehmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Regelkonformität kann durch Audits überprüft werden. b) Verstöße haben keine rechtlichen Folgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Audits ja, Folgen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die UWG ist für die Regelkonformität bei Werbung relevant. b) Interne Richtlinien sind rechtlich bindend wie Gesetze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "UWG ja, Richtlinien nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Regelkonformität schützt vor Reputationsverlust. b) Kundenwünsche haben Vorrang vor gesetzlichen Regeln.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz ja, Gesetze über Kundenwünsche"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein CRM-System kann die Regelkonformität unterstützen. b) Regelkonformität ist ohne Schulungen nicht möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CRM ja, Schulungen hilfreich aber nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

